import{_ as t,o as r,c as e,ag as o}from"./chunks/framework.D5hoimZQ.js";const p=JSON.parse('{"title":"🔬 科学快报 | 2026年7月30日（事后重建版）","description":"","frontmatter":{"sidebar":true},"headers":[],"relativePath":"science-log/src/reconstructed/2026-07-30.md","filePath":"science-log/src/reconstructed/2026-07-30.md"}'),n={name:"science-log/src/reconstructed/2026-07-30.md"};function i(s,a,l,u,g,h){return r(),e("div",null,[...a[0]||(a[0]=[o('<h1 id="🔬-科学快报-2026年7月30日-事后重建版" tabindex="-1">🔬 科学快报 | 2026年7月30日（事后重建版） <a class="header-anchor" href="#🔬-科学快报-2026年7月30日-事后重建版" aria-label="Permalink to &quot;🔬 科学快报 | 2026年7月30日（事后重建版）&quot;">​</a></h1><blockquote><p>⚠️ <strong>事后重建版</strong>：本文件<strong>不是</strong>当日发布原文。由 2026-11-05 依 arXiv / CrossRef <strong>按发布日期回溯检索</strong>生成，选题与排序均为事后判定，<strong>不代表历史原貌</strong>。 取证：CrossRef（Nature 0028-0836 / Science 10.1126 / PNAS 0027-8424）+ arXiv 日期区间 ｜ 重建日：2026-11-05</p></blockquote><hr><h2 id="🔬-科学前沿" tabindex="-1">🔬 科学前沿 <a class="header-anchor" href="#🔬-科学前沿" aria-label="Permalink to &quot;🔬 科学前沿&quot;">​</a></h2><h3 id="🧬-用-概率编码-给蛋白质做减法-raygun-把天然蛋白缩小-10–25" tabindex="-1">🧬 用&quot;概率编码&quot;给蛋白质做减法：Raygun 把天然蛋白缩小 10–25% <a class="header-anchor" href="#🧬-用-概率编码-给蛋白质做减法-raygun-把天然蛋白缩小-10–25" aria-label="Permalink to &quot;🧬 用&quot;概率编码&quot;给蛋白质做减法：Raygun 把天然蛋白缩小 10–25%&quot;">​</a></h3><p><strong>Miniaturizing and modifying natural proteins with Raygun</strong><em>Nature (2026)</em></p><p>蛋白质语言模型能给出每个残基的表征，但一直难以支撑&quot;大规模、保功能&quot;的序列改写。Devkota 等人提出 Raygun：把任意长度的蛋白编码成<strong>固定维度的概率分布</strong>而非变长向量，使不同长度的蛋白可直接比较；只靠&quot;替换率&quot;和&quot;长度变化&quot;两个参数，就能把蛋白缩小 10–25%（个别超过 50%）、也可扩张到超过天然尺寸，同时保留预测结构与功能位点。在细胞实验中验证了小型化后功能仍成立。</p><p>📎 DOI: <a href="https://doi.org/10.1038/s41586-026-10842-8" target="_blank" rel="noreferrer">10.1038/s41586-026-10842-8</a></p><h3 id="🧬-2-110-个着丝粒的全球图谱-着丝粒内部存在-军备竞赛" tabindex="-1">🧬 2,110 个着丝粒的全球图谱：着丝粒内部存在&quot;军备竞赛&quot; <a class="header-anchor" href="#🧬-2-110-个着丝粒的全球图谱-着丝粒内部存在-军备竞赛" aria-label="Permalink to &quot;🧬 2,110 个着丝粒的全球图谱：着丝粒内部存在&quot;军备竞赛&quot;&quot;">​</a></h3><p><strong>A global view of human centromere variation and evolution</strong><em>Nature (2026)</em></p><p>着丝粒序列高度重复，长期无法完整组装，个体与群体层面的多样性几乎空白。研究组装并刻画了来自 5 大洲、28 个群体的 2,110 个着丝粒，识别出 226 种着丝粒单倍型、1,870 种 α 卫星高阶重复变体；约 6% 存在双动粒位点、不到 1% 为三动粒。与 HPRC 的 5,747 个着丝粒比较后发现突变率有 20 倍差异，部分着丝粒带古人类渗入痕迹；四代 28 人家庭的验证显示<strong>动粒位点是着丝粒内突变最快的区域</strong>，据此提出着丝粒序列与蛋白间的&quot;军备竞赛&quot;模型。</p><p>📎 DOI: <a href="https://doi.org/10.1038/s41586-026-10841-9" target="_blank" rel="noreferrer">10.1038/s41586-026-10841-9</a></p><h3 id="🧬-转移灶的-免疫荒漠-是癌细胞自己造出来的" tabindex="-1">🧬 转移灶的&quot;免疫荒漠&quot;是癌细胞自己造出来的 <a class="header-anchor" href="#🧬-转移灶的-免疫荒漠-是癌细胞自己造出来的" aria-label="Permalink to &quot;🧬 转移灶的&quot;免疫荒漠&quot;是癌细胞自己造出来的&quot;">​</a></h3><p><strong>Spatiotemporal multiomics uncover tumor ecosystem dynamics during metastatic colonization</strong><em>Science (2026)</em></p><p>研究整合单细胞与空间多组学，在肝癌小鼠模型与人类转移灶中追踪播散肿瘤细胞（DTC）从单细胞定植到显性肺转移的全过程。发现一群<strong>静息态 Phgdh^high DTC</strong> 能躲过先天免疫清除，在微转移灶中短暂富集；它们通过 PHGDH 依赖的 H3K27me3 表观沉默关闭趋化因子转录，塑造出&quot;缺免疫细胞&quot;的微环境，从而推动转移扩张。</p><p>📎 DOI: <a href="https://doi.org/10.1126/science.adz7928" target="_blank" rel="noreferrer">10.1126/science.adz7928</a></p><h3 id="🧬-溶酶体衰老图谱-与-溶酶体贮积病-共享的代谢签名" tabindex="-1">🧬 溶酶体衰老图谱：与&quot;溶酶体贮积病&quot;共享的代谢签名 <a class="header-anchor" href="#🧬-溶酶体衰老图谱-与-溶酶体贮积病-共享的代谢签名" aria-label="Permalink to &quot;🧬 溶酶体衰老图谱：与&quot;溶酶体贮积病&quot;共享的代谢签名&quot;">​</a></h3><p><strong>Atlas of lysosomal aging reveals a metabolite signature shared with lysosomal storage disorders</strong><em>Science (2026)</em></p><p>团队用快速溶酶体分离工具，构建了脑、心、肌肉、白色脂肪的多组织溶酶体代谢物衰老图谱。衰老溶酶体蓄积<strong>甘油磷酸二酯类与胱氨酸</strong>——这两类物质正是青少年溶酶体贮积病、Batten 病与胱氨酸病的致病相关代谢物；其水平随年龄<strong>线性上升，且早于机体衰退</strong>。热量限制能减轻心与肌肉中的变化，但对脑无效。</p><p>📎 DOI: <a href="https://doi.org/10.1126/science.ady0832" target="_blank" rel="noreferrer">10.1126/science.ady0832</a></p><h3 id="⚛️-54-个量子点的硅基量子处理单元-交换型量子比特性能提升一个数量级" tabindex="-1">⚛️ 54 个量子点的硅基量子处理单元：交换型量子比特性能提升一个数量级 <a class="header-anchor" href="#⚛️-54-个量子点的硅基量子处理单元-交换型量子比特性能提升一个数量级" aria-label="Permalink to &quot;⚛️ 54 个量子点的硅基量子处理单元：交换型量子比特性能提升一个数量级&quot;">​</a></h3><p><strong>A digitally controlled silicon quantum processing unit</strong><em>Nature (2026)</em></p><p>硅基&quot;交换型（exchange-only）&quot;量子比特控制信号简单、与先进半导体工艺兼容，但噪声与布线 scalability 存疑。该工作把定制的<strong>低温 CMOS 控制器</strong>、高密度超导带状电缆与低噪声交换型比特器件集成为一套 QPU：芯片为 54 个交换耦合量子点的三轨阵列，可配置出最多 18 个交换型量子比特；单比特与纠缠操作性能比此前最好水平提升约一个数量级，并实现了 distance-5 重复码与 distance-2 量子纠错码，与仿真结果做了细致比对。</p><p>📎 DOI: <a href="https://doi.org/10.1038/s41586-026-10754-7" target="_blank" rel="noreferrer">10.1038/s41586-026-10754-7</a></p><hr><h2 id="🤖-ai-前沿" tabindex="-1">🤖 AI 前沿 <a class="header-anchor" href="#🤖-ai-前沿" aria-label="Permalink to &quot;🤖 AI 前沿&quot;">​</a></h2><h3 id="🎨-wait-让高频-等着-信号——频段感知的流匹配生成" tabindex="-1">🎨 WaiT：让高频&quot;等着&quot;信号——频段感知的流匹配生成 <a class="header-anchor" href="#🎨-wait-让高频-等着-信号——频段感知的流匹配生成" aria-label="Permalink to &quot;🎨 WaiT：让高频&quot;等着&quot;信号——频段感知的流匹配生成&quot;">​</a></h3><p><strong>WaiT for the Signal: Simple Frequency-Aware Flow-Matching</strong><em>arXiv (2026)</em></p><p>标准流匹配对所有空间频率一视同仁，但高频段远比粗结构更早&quot;退化成纯噪声&quot;。作者提出 Wavelet-aware image Transformer：用无损小波把生成拆成粗、细两个频段，高频段先保持纯噪声，等粗结构成形后再并入流共同精修。因 FID 的强下采样会丢弃细节，他们另设三轴原生分辨率评测；在 ImageNet 512×512 上像素空间 FID 达 1.43，三轴均 Pareto 最优，采样算力最多省 50%，2B 模型创下像素空间 FID 1.3 的新 SOTA。</p><p>📎 arXiv: <a href="https://arxiv.org/abs/2607.28760" target="_blank" rel="noreferrer">2607.28760</a></p><h3 id="📊-github-copilot-生产级轨迹首次刻画-3-2m-用户、761m-次-llm-调用" tabindex="-1">📊 GitHub Copilot 生产级轨迹首次刻画：3.2M 用户、761M 次 LLM 调用 <a class="header-anchor" href="#📊-github-copilot-生产级轨迹首次刻画-3-2m-用户、761m-次-llm-调用" aria-label="Permalink to &quot;📊 GitHub Copilot 生产级轨迹首次刻画：3.2M 用户、761M 次 LLM 调用&quot;">​</a></h3><p><strong>Agentic Coding in the Wild: Characterizing GitHub Copilot Traces at Production Scale</strong><em>arXiv (2026)</em></p><p>AI 编程智能体把多步推理与工具执行交织，负载形态与聊天机器人完全不同。本文基于 2026 年 6 月采样的 Copilot 轨迹（320 万用户、1,300 万会话、7.61 亿次 LLM 调用、95 万亿 token）做首个生产规模刻画：会话由稀疏的用户轮次构成，每轮展开为几乎总伴随工具调用的自主循环；<strong>KV cache 命中率在轮内平均 90%，跨轮边界降至 55%</strong>，模型切换或上下文压缩后会剧烈失效；token 消耗、时长与工具调用呈长尾分布。</p><p>📎 arXiv: <a href="https://arxiv.org/abs/2608.00101" target="_blank" rel="noreferrer">2608.00101</a></p><h3 id="🛠-修-bug-智能体-测试通过-有多少真在测这个-bug-46-不含判别信息" tabindex="-1">🛠 修 bug 智能体&quot;测试通过&quot;有多少真在测这个 bug？46% 不含判别信息 <a class="header-anchor" href="#🛠-修-bug-智能体-测试通过-有多少真在测这个-bug-46-不含判别信息" aria-label="Permalink to &quot;🛠 修 bug 智能体&quot;测试通过&quot;有多少真在测这个 bug？46% 不含判别信息&quot;">​</a></h3><p><strong>Validation Evidence in LLM Repair Agents: How Much of What Passes Actually Tests the Bug?</strong><em>arXiv (2026)</em></p><p>修复智能体看到测试通过就当作对缺陷的证据，本文量化这种推断何时成立。作者提出 BSG-VA：在精确工作树状态捕获每条验证命令，抽出 test-only 补丁，再在原始 buggy 代码（B）、候选状态（S）、开发者金修（G）上重放，为每个事件判定证据角色。在 110 个任务、643 次 rollout 的 3,730 个事件中，<strong>46.0% 的阳性可比事件不含任何 bug 判别信息</strong>，23.8% 的基线 rollout 完全靠这类证据收工；把 B 重放结果回灌给智能体后，证据不足即收工的比例相对注意力匹配对照组降低 7.8 个百分点（p = 0.0029）。</p><p>📎 arXiv: <a href="https://arxiv.org/abs/2607.28871" target="_blank" rel="noreferrer">2607.28871</a></p><h3 id="🧠-长期陪伴的-ai-会-人格崩塌-轨迹回忆准确率仅-44-4" tabindex="-1">🧠 长期陪伴的 AI 会&quot;人格崩塌&quot;：轨迹回忆准确率仅 44.4% <a class="header-anchor" href="#🧠-长期陪伴的-ai-会-人格崩塌-轨迹回忆准确率仅-44-4" aria-label="Permalink to &quot;🧠 长期陪伴的 AI 会&quot;人格崩塌&quot;：轨迹回忆准确率仅 44.4%&quot;">​</a></h3><p><strong>Best Friends, Not Forever: Evaluating Long-Horizon Persona Collapse and Behavioral Drift in AI Companions</strong><em>arXiv (2026)</em></p><p>AI 伴侣需要长期维持固定角色与共享历史，但局部可接受的回复并不保证二者持续。作者定义两种可观测失效：人格崩塌（角色、边界、价值观、风格的丧失）与行为漂移（这些属性的渐进或周期性侵蚀），并用 ANCHOR 审计分离测量&quot;人格扮演&quot;与&quot;轨迹回忆&quot;：2,008 段对话、27 个人格、9 种交互节奏、3 种记忆设置、4 个模型。Identity Probe 用封存 102 题问卷加逐轮判分，Trajectory Probe 用 35 个对话库的 110 道校准反事实题。结果没有任何模型或配置能可靠保持两个维度：<strong>轨迹准确率平均仅 44.4%</strong>，用户状态回忆接近四选一的随机水平。</p><p>📎 arXiv: <a href="https://arxiv.org/abs/2607.28818" target="_blank" rel="noreferrer">2607.28818</a></p><h3 id="📏-一致不等于质量-盲评专家眼中人机编码质量无显著差异" tabindex="-1">📏 一致不等于质量：盲评专家眼中人机编码质量无显著差异 <a class="header-anchor" href="#📏-一致不等于质量-盲评专家眼中人机编码质量无显著差异" aria-label="Permalink to &quot;📏 一致不等于质量：盲评专家眼中人机编码质量无显著差异&quot;">​</a></h3><p><strong>Agreement Is Not Quality: Blind Expert Verification of Human and LLM Qualitative Coding When Human Consensus Is Not Ground Truth</strong><em>arXiv (2026)</em></p><p>LLM 辅助质性编码的评测几乎都以&quot;与人类编码一致&quot;为准，前提是人类编码即金标准。本文给出该前提失效的实证：5 个 LLM 系统与 3 名受训人类编码员各自用 72 项层级码本处理 K-12 AI 平台的 2,560 条教育者留言；另请独立领域专家在不知来源的情况下判 855 组两两比较。人机一致（平均 Jaccard 0.30）远低于人人一致（0.52），按惯例会判 LLM 更差，但盲评专家对人类与 LLM 编码的偏好率几乎相同（51.5% vs 48.5%，p = 0.537），Bradley-Terry 排名中两个 LLM 高于三名人类编码员中的两位；若干实质码上，人类共识本身编码了共同偏见。</p><p>📎 arXiv: <a href="https://arxiv.org/abs/2607.28890" target="_blank" rel="noreferrer">2607.28890</a></p><hr><blockquote><p>📅 日期：2026-07-30 ｜ ⚠️ 事后重建版 ｜ 📂 科学前沿 5 篇 | 🤖 AI前沿 5 篇 🧾 期号：（第 ? 期 · 事后重建版）</p></blockquote>',48)])])}const d=t(n,[["render",i]]);export{p as __pageData,d as default};
